import mujoco, numpy as np, time
T=mujoco.mjtTimer
names={v:k for k,v in vars(T).items() if k.startswith('mjTIMER_')}
def profile(kw, label):
    m = mujoco.MjModel.from_xml_path("model_ref.xml")
    for k,v in kw.items(): setattr(m.opt,k,v)
    d = mujoco.MjData(m)
    rng=np.random.default_rng(1); d.qpos += rng.normal(0,0.01,size=d.qpos.shape)
    mujoco.mj_forward(m,d)
    N=3000
    t0=time.perf_counter()
    for _ in range(N): mujoco.mj_step(m,d)
    tot=(time.perf_counter()-t0)/N*1e6
    print(f"--- {label}: {tot:.1f} us/step")
    for i in range(len(d.timer.duration)):
        if d.timer.number[i]:
            us=d.timer.duration[i]*1e6/N
            if us>0.3: print(f"   {names.get(i,i):28s} {us:8.2f}")
profile({}, "REF Newton")
profile(dict(solver=mujoco.mjtSolver.mjSOL_PGS), "PGS")
EOF
